import {bindDocumentExports,documentExportButtons} from './document-export.mjs';
import {mountToolJobPanel} from './tool-job-panel.mjs';
import {literatureParagraphs,selectReadingMaterials,validateLiteratureAiOutput,literatureAiExport} from './literature-ai-model.mjs';
import {esc,icon,download,formatDate} from './ui.mjs';
const names={read:'AI 研读',answer:'原文问答',translate:'文献翻译'},languages=[['zh-CN','简体中文'],['en','英语'],['ja','日语'],['ko','韩语'],['de','德语'],['fr','法语']];
function stylesheet(doc){if(doc.querySelector('[data-literature-ai-style]'))return;const link=doc.createElement('link');link.rel='stylesheet';link.href='/workspace/literature-ai.css';link.dataset.literatureAiStyle='';doc.head.append(link);}
export function mountLiteratureAi({container,ctx,getPaper,updatePaper,initialOperation='read'}){
 stylesheet(container.ownerDocument);const win=container.ownerDocument.defaultView;let live=true,panel=null,operation=Object.hasOwn(names,initialOperation)?initialOperation:'read';const initial=getPaper(),parts=literatureParagraphs(initial.text);let last=0,length=0;for(const p of parts){if(length+p.text.length>32000||last>=20)break;length+=p.text.length;last++;}const restored=initial.aiDraft||{},draft={start:1,end:last||1,question:'',language:'zh-CN',...restored};if(!languages.some(([code])=>code===draft.language))draft.language='zh-CN';
 const current=()=>live&&container.isConnected&&getPaper()?.id===initial.id;
 const persistDraft=()=>{if(!current())return false;try{updatePaper(p=>({...p,aiDraft:{...draft}}));return true;}catch{ctx.notify?.('研读设置未能保存，当前输入仍保留，请导出备份。');return false;}};
 function snapshot(){const paper=getPaper(),materials=selectReadingMaterials(paper,draft.start,draft.end),question=String(draft.question||'').trim();if(operation==='answer'&&!question)throw Error('请先填写要询问的原文问题。');if(operation==='answer'&&question.length>1500)throw Error('原文问题最多 1,500 字符，请简要描述。');if(operation==='translate'&&materials.some(m=>m.text.length>3500))throw Error('翻译每段最多 3,500 字符，请先在编辑信息中按自然段拆分原文。');return {title:paper.title.slice(0,200),text:materials.map(m=>m.text).join('\n\n'),materials,question:operation==='answer'?question:'',language:operation==='translate'?draft.language:'zh-CN',requirements:operation==='read'?'基于所选原文整理研究问题、方法、发现与局限；原文未说明的事项明确标注未提供。':operation==='answer'?'仅依据所选原文回答问题；无法从原文判断时明确说明。':'保留术语、数字、引用标记与段落顺序，不添加原文没有的信息。',context:{paperId:paper.id,scope:paper.scope,paragraphIds:materials.map(m=>m.id)}};}
 function render(){panel?.dispose();if(!current())return;const paper=getPaper(),results=(paper.aiResults||[]).slice().reverse();container.innerHTML=`<section class="card lit-ai-card"><header class="lit-ai-head"><div><span class="lit-ai-kicker">READ WITH EVIDENCE</span><h2>让每一条理解，都能回到原文</h2><p>${paper.scope==='abstract'?'当前仅有摘要；研读和翻译只处理你选择的摘要段落。':'选择已导入的原文段落，生成解读、提出问题或制作对照译文。'}</p></div><span class="lit-ai-source-badge">${esc(parts.length)} 个原文片段</span></header>${paper.scope==='metadata'||!parts.length?'<div class="lit-ai-empty">当前仅保存了题录信息。请先通过“编辑信息”补充正文或摘要，才能进行研读与翻译。</div>':`<nav class="lit-ai-tabs" aria-label="研读方式">${Object.entries(names).map(([key,name])=>`<button type="button" data-lit-ai-operation="${key}" class="${key===operation?'active':''}" aria-pressed="${key===operation}">${icon(key==='translate'?'language':key==='answer'?'search':'book',18)}${name}</button>`).join('')}</nav><div class="lit-ai-inputs"><fieldset><legend>本次原文范围</legend><div class="lit-ai-range"><label>从第 <input type="number" data-lit-ai-start min="1" max="${parts.length}" value="${esc(draft.start)}" aria-label="起始原文段落"> 段</label><label>到第 <input type="number" data-lit-ai-end min="1" max="${parts.length}" value="${esc(draft.end)}" aria-label="结束原文段落"> 段</label><span data-lit-ai-range-status role="status"></span></div><p>每次最多 20 段、32,000 字符；仅处理选中原文，未选择的段落不会声称已读。${parts.some(p=>p.split)?' 长段已按连续原文片段拆分，原始导入正文保留。':''}</p></fieldset>${operation==='answer'?`<label class="lit-ai-question">你想了解什么？<textarea data-lit-ai-question rows="3" maxlength="1500" placeholder="例如：原文的方法适用于哪些场景？请指出原文依据。">${esc(draft.question)}</textarea></label>`:operation==='translate'?`<label class="lit-ai-language">翻译成<select data-lit-ai-language>${languages.map(([id,label])=>`<option value="${id}" ${id===draft.language?'selected':''}>${label}</option>`).join('')}</select></label>`:'<p class="lit-ai-directions">整理研究问题、方法、发现与局限，并保留可定位的原文依据。</p>'}</div><div class="lit-ai-actions"><button class="btn primary" type="button" data-lit-ai-open>${icon('spark',17)}${operation==='answer'?'根据原文回答':operation==='translate'?'生成对照译文':'开始 AI 研读'}</button><span>先确认费用，再提交；结果审核后保存。</span></div><div data-lit-ai-panel hidden></div>`}<section class="lit-ai-results"><header><h3>已保存的研读与翻译</h3><span>${results.length} 份 · 当前浏览器</span></header>${results.map((result,index)=>`<details class="lit-ai-result" ${index===0?'open':''}><summary><b>${esc(names[result.operation]||'研读结果')}${result.question?' · '+esc(result.question.slice(0,70)):''}</b><span>${esc(formatDate(result.createdAt))}</span></summary><p class="lit-ai-result-scope">${result.sourceScope==='abstract'?'仅基于所选摘要':'仅基于所选导入正文'} · ${result.materials?.length||0} 段${result.language?' · '+esc(languages.find(([id])=>id===result.language)?.[1]||result.language):''}</p>${result.operation==='translate'?`<div class="lit-ai-translations">${(result.output.segments||[]).map(part=>`<section><div><span>${esc(part.id)} · 原文</span><p>${esc(part.source)}</p></div><div><span>译文 · 待核对术语与事实</span><textarea class="lit-ai-translation-edit" data-lit-ai-result="${esc(result.id)}" data-lit-ai-segment="${esc(part.id)}" rows="6" maxlength="7000" aria-label="编辑 ${esc(part.id)} 译文">${esc(part.translation)}</textarea></div></section>`).join('')}</div>`:`<label class="lit-ai-edit-label">研读内容（可修改）<textarea class="lit-ai-answer" data-lit-ai-result="${esc(result.id)}" data-lit-ai-text rows="8" maxlength="10000">${esc(result.output.text)}</textarea></label><h4>原文依据</h4>${(result.output.citations||[]).map(c=>`<blockquote><a href="#" data-lit-source="${esc(c.sourceId)}" data-lit-result="${esc(result.id)}">第 ${esc(c.sourceId.replace(/^p/,''))} 段原文 ↗</a><p>${esc(c.quote)}</p></blockquote>`).join('')}`}<button type="button" class="btn secondary" data-lit-ai-export="${esc(result.id)}">导出${result.operation==='translate'?'对照译文':'研读结果'} TXT</button>${documentExportButtons('lit-ai-'+result.id)}<button type="button" class="btn secondary" data-lit-ai-remove="${esc(result.id)}">移除此本地结果</button><p class="lit-ai-export-status" id="lit-ai-${esc(result.id)}-status" role="status"></p></details>`).join('')||'<p class="lit-ai-empty">核对并采纳生成内容后，会在这里保留结果与本次原文依据。</p>'}</section></section>`;
 if(!parts.length||paper.scope==='metadata'){bindResults();return;}
 const $=s=>container.querySelector(s);const rangeStatus=()=>{try{const materials=selectReadingMaterials(getPaper(),draft.start,draft.end);$('[data-lit-ai-range-status]').textContent=`已选 ${materials.length} 段 · ${materials.reduce((n,m)=>n+m.text.length,0).toLocaleString('zh-CN')} 字符`;}catch(error){$('[data-lit-ai-range-status]').textContent=error.message;}};rangeStatus();
 for(const [selector,key] of [['[data-lit-ai-start]','start'],['[data-lit-ai-end]','end'],['[data-lit-ai-question]','question'],['[data-lit-ai-language]','language']])$(selector)?.addEventListener('input',e=>{draft[key]=['start','end'].includes(key)?Number(e.target.value):e.target.value;persistDraft();rangeStatus();panel?.inputChanged?.();});
 container.querySelectorAll('[data-lit-ai-operation]').forEach(button=>button.onclick=()=>{operation=button.dataset.litAiOperation;render();});
 panel=mountToolJobPanel({container:$('[data-lit-ai-panel]'),ctx,kind:'literature',operation,getSnapshot:snapshot,initialState:paper.aiJobStates?.[operation]||{},isCurrent:current,onStateChange:state=>{if(current())try{updatePaper(p=>({...p,aiJobStates:{...p.aiJobStates,[operation]:state}}));}catch{ctx.notify?.('任务进度未能保存在浏览器；已提交任务可在任务中心查看。');throw Error('本地任务记录保存失败，已阻止本次新提交。请检查存储空间后重试。');}},onApply:(output,item)=>{const frozen=snapshot(),checked=validateLiteratureAiOutput(output,frozen,operation);let added=false;updatePaper(p=>{const existing=p.aiResults||[];if(existing.some(result=>result.jobId===item.id))return p;if(existing.length>=30)throw Error('每篇文献最多保存 30 份研读结果，请先导出备份并整理。');added=true;return {...p,aiResults:[...existing,{id:win.crypto.randomUUID(),jobId:item.id,operation,question:frozen.question,language:operation==='translate'?frozen.language:'',sourceScope:p.scope,materials:frozen.materials,output:checked,createdAt:new Date().toISOString()}]};});ctx.notify?.(added?'结果和原文依据已保存到当前浏览器。':'这份结果已经保存。');render();}});
 $('[data-lit-ai-open]').onclick=()=>void panel.open();bindResults();
 }
 function bindResults(){container.querySelectorAll('[data-lit-ai-remove]').forEach(button=>button.onclick=()=>{if(!win.confirm('仅移除此浏览器中的研读或翻译结果。原文、笔记与账户任务保留；请先导出需要保留的内容。确认移除？'))return;try{updatePaper(p=>({...p,aiResults:(p.aiResults||[]).filter(result=>result.id!==button.dataset.litAiRemove)}));render();ctx.notify?.('本地结果已移除，原文与账户任务仍保留。');}catch(error){ctx.notify?.(error.message||'移除失败，原结果仍保留。');}});container.querySelectorAll('[data-lit-ai-result][data-lit-ai-text],[data-lit-ai-result][data-lit-ai-segment]').forEach(editor=>editor.oninput=()=>{const status=container.ownerDocument.getElementById('lit-ai-'+editor.dataset.litAiResult+'-status');if(!editor.value.trim()){status.textContent='内容不能为空，当前输入尚未保存。';return;}try{updatePaper(p=>({...p,aiResults:p.aiResults.map(result=>{if(result.id!==editor.dataset.litAiResult)return result;const output=structuredClone(result.output);if(editor.hasAttribute('data-lit-ai-text'))output.text=editor.value;else{output.segments=output.segments.map(part=>part.id===editor.dataset.litAiSegment?{...part,translation:editor.value}:part);output.text=output.segments.map(part=>part.translation).join('\n\n');}return {...result,output,editedAt:new Date().toISOString()};})}));status.textContent='修改已自动保存到当前浏览器，原文依据保留。';}catch(error){status.textContent=error.message||'修改保存失败，当前输入仍保留，请复制备份。';}});for(const result of getPaper().aiResults||[])bindDocumentExports('lit-ai-'+result.id,()=>literatureAiExport(getPaper(),getPaper().aiResults.find(r=>r.id===result.id)),()=>getPaper().title+'-'+names[result.operation],container.ownerDocument.getElementById('lit-ai-'+result.id+'-status'));container.querySelectorAll('[data-lit-ai-export]').forEach(button=>button.onclick=()=>{const paper=getPaper(),result=(paper.aiResults||[]).find(r=>r.id===button.dataset.litAiExport);if(result){download(paper.title+'-'+names[result.operation]+'.txt',literatureAiExport(paper,result));ctx.notify?.('已发起下载，原文依据与译文对应关系一并导出。');}});container.querySelectorAll('[data-lit-source]').forEach(link=>link.onclick=e=>{e.preventDefault();const paper=getPaper(),result=(paper.aiResults||[]).find(r=>r.id===link.dataset.litResult),frozen=result?.materials?.find(m=>m.id===link.dataset.litSource),actual=literatureParagraphs(paper.text).find(p=>p.id===link.dataset.litSource);const source=container.ownerDocument.getElementById('lit-source-'+link.dataset.litSource);if(!source||actual?.text!==frozen?.text){ctx.notify?.('原文已修改，请以本次结果导出的原文依据为准。');return;}const textPane=container.ownerDocument.getElementById('reader-text-pane'),notesPane=container.ownerDocument.getElementById('reader-notes-pane');if(textPane)textPane.hidden=false;if(notesPane)notesPane.hidden=true;container.ownerDocument.querySelectorAll('[data-read-tab]').forEach(b=>b.classList.toggle('active',b.dataset.readTab==='text'));source.scrollIntoView({behavior:'smooth',block:'center'});source.classList.add('lit-ai-source-highlight');win.setTimeout(()=>source.classList.remove('lit-ai-source-highlight'),3000);});}
 render();return {dispose(){live=false;panel?.dispose();},getState:()=>({...draft})};
}
